<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $user = $args['user']; ?><section class="sd-profile-section"><h2><?php esc_html_e( 'About', 'social-discovery' ); ?></h2><p><?php echo esc_html( sd_member_bio( $user->ID ) ?: __( 'This member has not added a public bio yet.', 'social-discovery' ) ); ?></p><?php $location = function_exists( 'sd_core_profile_field' ) ? sd_core_profile_field( $user->ID, 'Location', get_user_meta( $user->ID, 'sd_profile_location', true ) ) : get_user_meta( $user->ID, 'sd_profile_location', true ); if ( $location ) : ?><p class="sd-profile-meta"><?php echo esc_html( $location ); ?></p><?php endif; ?></section>
